public class BankAccount {
    private String ownerName;
    private double balance = 0.0;

    // Konstruktor, der ownerName initialisiert
    public BankAccount(String ownerName) {
        this.ownerName = ownerName;
    }

    // Konstruktor, der ownerName als Standardwert "Unknown" setzt
    public BankAccount() {
        this.ownerName = "Unknown";
    }

    // Getter-Methoden
    public String getOwnerName() {
        return ownerName;
    }

    public double getBalance() {
        return balance;
    }

    // Setter-Methoden
    public void setOwnerName(String ownerName) {
        this.ownerName = ownerName;
    }

    // deposit(double amount) Methode
    public String deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            return String.format("Your current balance is €%.1f", balance);
        } else {
            return "The amount must be greater than zero.";
        }
    }

    // withdraw(double amount) Methode
    public String withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return String.format("Your current balance is €%.1f", balance);
        } else {
            return "You have insufficient funds.";
        }
    }

    // main method for testing
    public static void main(String[] args) {
        BankAccount account1 = new BankAccount("John Doe");
        System.out.println(account1.deposit(100.0)); // Your current balance is €100.0
        System.out.println(account1.withdraw(50.0)); // Your current balance is €50.0
        System.out.println(account1.withdraw(100.0)); // You have insufficient funds.
        System.out.println(account1.deposit(-10.0)); // The amount must be greater than zero.
        System.out.println(account1.getBalance()); // 50.0

        BankAccount account2 = new BankAccount();
        System.out.println(account2.deposit(200.0)); // Your current balance is €200.0
        System.out.println(account2.withdraw(150.0)); // Your current balance is €50.0
    }
}
