public class Time {
    public static void main(String[] args) {
        // a) Legen Sie Variablen mit den Namen hour, minute und second an. Weisen Sie den Variablen die Werte für 15 Uhr, 10 Minuten und 30 Sekunden zu. Das ist eine fiktive Startzeit.
        int hour = 15;
        int minute = 10;
        int second = 30;

        // b) Lassen Sie das Programm nun berechnen, wie viele Sekunden seit Mitternacht vergangen sind und geben Sie die Antwort in dem folgenden Format aus:
        int secondsSinceMidnight = hour * 3600 + minute * 60 + second;
        System.out.println(secondsSinceMidnight + " seconds have passed since midnight.");

        // c) Berechnen und geben Sie in der nächsten Zeile aus, wie viele Sekunden der Tag noch übrig haben. Das Ausgabeformat ist:
        int secondsUntilMidnight = (24 * 3600) - secondsSinceMidnight;
        System.out.println(secondsUntilMidnight + " seconds are left until midnight.");

        // d) Erstellen Sie nun drei Variablen, welche die fiktive Zeit 15 Uhr, 17 Minuten und 51 Sekunden repräsentieren. Lassen Sie das Programm berechnen, wie viel Zeit von der fiktiven Startzeit bis zu der fiktiven aktuellen Zeit vergangen ist. Geben Sie die Antwort in der nächsten Zeile nach dem folgenden Format aus.
        int currentHour = 15;
        int currentMinute = 17;
        int currentSecond = 51;
        int currentSecondsSinceMidnight = currentHour * 3600 + currentMinute * 60 + currentSecond;
        int secondsPassedSinceStart = currentSecondsSinceMidnight - secondsSinceMidnight;
        System.out.println("Since I started with the task " + secondsPassedSinceStart + " seconds have passed.");
    }
}
