public class Time {
    public static void main(String[] args) {
        // Task a: Define variables for the start time
        int startHour = 15;
        int startMinute = 10;
        int startSecond = 30;

        // Task b: Convert start time to seconds since midnight
        int startSeconds = startHour * 3600 + startMinute * 60 + startSecond;

        // Task c: Print seconds passed since midnight
        System.out.println(startSeconds + " seconds have passed since midnight.");

        // Task d: Calculate and print seconds left until midnight
        int secondsUntilMidnight = 24 * 3600 - startSeconds;
        System.out.println(secondsUntilMidnight + " seconds are left until midnight.");

        // Task e: Define variables for the current time
