public class BankAccount {
    private String ownerName;
    private double balance;

    // Constructor 1: initializes ownerName, default balance is 0.0
    public BankAccount(String ownerName) {
        this.ownerName = ownerName;
        this.balance = 0.0;
    }

    // Constructor 2: default ownerName is "Unknown", default balance is 0.0
    public BankAccount() {
        this.ownerName = "Unknown";
        this.balance = 0.0;
    }

    // Getter for ownerName
    public String getOwnerName() {
        return ownerName;
    }

    // Setter for ownerName
    public void setOwnerName(String ownerName) {
        this.ownerName = ownerName;
    }

    // Getter for balance
    public double getBalance() {
        return balance;
    }

    // Method to deposit a positive amount
    public String deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            return String.format("Your current balance is €%.2f", balance);
        } else {
            return "The amount must be greater than zero.";
        }
    }

    // Method to withdraw a positive amount if sufficient funds are available
    public String withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return String.format("Your current balance is €%.2f", balance);
        } else if (balance < amount) {
            return "You have insufficient funds.";
        } else {
            return "The amount must be greater than zero.";
        }
    }

    public static void main(String[] args) {
        // Example usage of the BankAccount class
        BankAccount account = new BankAccount("John Doe");
        System.out.println(account.deposit(100.0)); // Your current balance is €100.0
        System.out.println(account.withdraw(50.0));  // Your current balance is €50.0
        System.out.println(account.withdraw(60.0));  // You have insufficient funds.
    }
}
