public class BankAccount {
    private String ownerName;
    private double balance = 0.0;

    // Constructor with ownerName initialization
    public BankAccount(String ownerName) {
        this.ownerName = ownerName;
    }

    // Constructor with default values
    public BankAccount() {
        this.ownerName = "Unknown";
    }

    // Getter for ownerName
    public String getOwnerName() {
        return ownerName;
    }

    // Setter for ownerName
    public void setOwnerName(String ownerName) {
        this.ownerName = ownerName;
    }

    // Getter for balance
    public double getBalance() {
        return balance;
    }

    // Method to deposit money
    public String deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            return String.format("Your current balance is €%.1f", balance);
        } else {
            return "The amount must be greater than zero.";
        }
    }

    // Method to withdraw money
    public String withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return String.format("Your current balance is €%.1f", balance);
        } else {
            return "You have insufficient funds.";
        }
    }

    // Main method for testing
    public static void main(String[] args) {
        BankAccount account = new BankAccount("John Doe");
        System.out.println(account.deposit(100.0));
        System.out.println(account.withdraw(50.0));
        System.out.println(account.withdraw(60.0));
    }
}
