public class BankAccount {
    private String ownerName;
    private double balance;

    // Constructor with ownerName, balance initialized to 0.0
    public BankAccount(String ownerName) {
        this.ownerName = ownerName;
        this.balance = 0.0;
    }

    // Constructor with no parameters, ownerName set to "Unknown", balance initialized to 0.0
    public BankAccount() {
        this.ownerName = "Unknown";
        this.balance = 0.0;
    }

    // Getter for ownerName
    public String getOwnerName() {
        return ownerName;
    }

    // Setter for ownerName
    public void setOwnerName(String ownerName) {
        this.ownerName = ownerName;
    }

    // Getter for balance
    public double getBalance() {
        return balance;
    }

    // Method to deposit money into the account
    public String deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            return "Your current balance is €" + String.format("%.2f", balance);
        } else {
            return "The amount must be greater than zero.";
        }
    }

    // Method to withdraw money from the account
    public String withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return "Your current balance is €" + String.format("%.2f", balance);
        } else {
            return "You have insufficient funds.";
        }
    }

    public static void main(String[] args) {
        // Create an instance of BankAccount
        BankAccount account = new BankAccount("John Doe");

        // Deposit money and print the result
        System.out.println(account.deposit(100.0));

        // Withdraw money and print the result
        System.out.println(account.withdraw(50.0));

        // Try to withdraw more money than available and print the result
        System.out.println(account.withdraw(100.0));
    }
}
