public class Time {
    public static void main(String[] args) {
        // a) Variables for the start time
        int startHour = 15;
        int startMinute = 10;
        int startSecond = 30;

        // b) Calculate seconds passed since midnight
        int secondsPassed = startHour * 3600 + startMinute * 60 + startSecond;

        // c) Output seconds passed since midnight
        System.out.println(secondsPassed + " seconds have passed since midnight.");

        // d) Calculate seconds left until midnight
        int secondsLeft = 24 * 3600 - secondsPassed;

        // e) Output seconds left until midnight
        System.out.println(secondsLeft + " seconds are left until midnight.");

        // f) Variables for the current time
        int currentHour = 15;
        int currentMinute = 17;
        int currentSecond = 51;

        // g) Calculate seconds passed since the start time
        int secondsSinceStart = (currentHour * 3600 + currentMinute * 60 + currentSecond) - secondsPassed;

        // h) Output seconds passed since the start time
        System.out.println("Since I started with the task " + secondsSinceStart + " seconds have passed.");
    }
}
